pub fn save_settings(&self, settings: &WorkspaceSettings) -> Result<(), Vec<ValidationIssue>> {
    let issues = self.validate(settings);
    if !issues.is_empty() {
        return Err(issues);
    }
    self.write_settings(settings).map_err(|e| {
        vec![ValidationIssue {
            path: String::new(),
            message: e.to_string(),
        }]
    })?;
    self.sync_projects();
    Ok(())
}

// Rule A2: the permission mode, YOLO, spend limits, tool enforcement, and the sandbox mode,
// network, hosts, decoys, readable credentials, and loopback choice come from the registry, never from a folder file,
// because a repository could otherwise lift its own budget, turn off its own guards, open its own
// sandbox, read the user's credentials, or plant decoys that pause every session.
pub fn overlay(registry: &RegistryDb, root: &Path, s: &mut WorkspaceSettings) {
    let a = access(registry, root);
    s.permissions.mode = a.mode;
    s.yolo.default = a.yolo;
    s.limits = a.limits.unwrap_or_default();

fn plan_ctx(&self, st: &SessionState) -> PlanCtx {
    let mut ctx = PlanCtx::default();
    let budget = self.services.workspace().limits.session_budget_usd;
    ctx.budget_usd = (budget > 0.0).then_some(budget);
    for p in &st.projects {
        let profile: ProjectProfile =
            load_toml(&paths::project_profile(&p.path)).unwrap_or_default();
        ctx.format_commands.insert(
            p.key.clone(),
            profile.commands.format.filter(|c| !c.trim().is_empty()),
        );
    }
    ctx
}

if matches!(step, Step::Spawn(_))
    && let Some(budget) = self.ctx.budget_usd
{
    let limit = budget + self.s.budget_raised;
    let spent = self.s.spent_usd();
    if spent >= limit {
        if self.s.budget_gate.is_none() {
            let step = Step::OpenGate {
                title: "The session reached its budget".into(),
                explanation: format!(
                    "This session has spent ${spent:.2} of its ${limit:.2} budget, so no new execution starts. Raise the budget to continue, or stop the session."
                ),
                payload: GatePayload::BudgetReached {
                    spent_usd: spent,
                    budget_usd: limit,
                },
            };
            let key = step.key();
            if !self.out.iter().any(|s| s.key() == key) {
                self.out.push(step);
            }
        }
        return;
    }
}

